const data = $input.first().json;

const items = data.items.flatMap(item => {
  let baseItems = [{
    name: item.productName,
    quantity: item.quantity,
    price: item.basePrice,
    category: item.category
  }];

  if (item.addOns && item.addOns.length > 0) {
    item.addOns.forEach(addon => {
      baseItems.push({
        name: `Add-on: ${addon.ingredientName || addon.addOnName}`,
        quantity: addon.quantity,
        price: addon.ingredientPrice || addon.addOnPrice,
        category: "Add-ons"
      });
    });
  }

  return baseItems;
});

const deliveryFee = data.deliveryMethod === "Delivery" ? 20 : 0;
if (deliveryFee > 0) {
  items.push({
    name: "Delivery Fee",
    quantity: 1,
    price: deliveryFee,
    category: "Service"
  });
}

// Add discount if promo is applied
if (data.appliedPromo) {
  items.push({
    name: `Discount: ${data.appliedPromo.discountPercentage}% off ${data.appliedPromo.event}`,
    quantity: 1,
    price: -data.appliedPromo.discountAmount,
    category: "Discount"
  });
}

const email = data.deliveryAddress?.email || "";
const payerEmail = email.trim() !== "" ? email : undefined;

const transactionId = data.transactionId;

// Calculate the amount as the sum of all item prices (including delivery and discount)
const amount = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

const invoicePayload = {
  external_id: transactionId,
  description: "Blessings Cafe Payment",
  merchant_profile_picture_url: "https://i.ibb.co/KcNnHLxH/Blessings-Logo.png",
  items: items,
  amount: amount,
  customer_name: data.userId,
  customer_phone: data.deliveryAddress?.phone || "",
  should_send_email: Boolean(payerEmail),
  payment_methods: ["GCASH", "PAYMAYA", "SHOPEEPAY", "QRPH"],
  invoice_duration: 600
};

if (payerEmail) {
  invoicePayload.payer_email = payerEmail;
}

return { json: invoicePayload };

// Extract and validate order information
const input = $input.first().json;

return {
  json: {
    userId: input.userId,
    customerName: input.customerName,
    customerEmail: input.customerEmail,
    customerPhone: input.customerPhone,
    items: input.items,
    subtotal: input.subtotal,
    totalAmount: input.totalAmount,
    deliveryMethod: input.deliveryMethod,
    deliveryAddress: input.deliveryAddress,
    orderNotes: input.orderNotes,
    transactionId: input.transactionId,
    appliedPromo: input.appliedPromo,
    paymentMethod: input.paymentMethod
  }
};

let psid = "unknown";

if ($input.item.json.query?.psid) {
  psid = $input.item.json.query.psid;
} else if ($input.item.json.body?.psid) {
  psid = $input.item.json.body.psid;
} else if ($input.item.json.psid) {
  psid = $input.item.json.psid;
}

return {
  json: {
    psid: psid
  }
};

// Get current date and time in Philippines timezone (UTC+8)
const now = new Date();
const philippinesTime = new Date(now.getTime() + 8 * 60 * 60 * 1000);
const formattedDate = philippinesTime.toISOString();

function pad(num, size = 2) {
  return num.toString().padStart(size, '0');
}
const idDate =
  pad(philippinesTime.getMonth() + 1) +
  pad(philippinesTime.getDate()) +
  pad(philippinesTime.getHours()) +
  pad(philippinesTime.getMinutes()) +
  pad(philippinesTime.getSeconds());
const transactionId = `${idDate}-BLESSINGSCAFE`;

let deliveryMethod = "Delivery";
let deliveryAddress = null;
let isDeliverable = false;
let nextAction = "PAYMENT";
let psid = "unknown";
const paymentMethod = "E-Payment";

const rawInput = $input.item.json;

if ((rawInput && rawInput[0] && rawInput[0].postback === "STORE_PICKUP") ||
    (rawInput && rawInput.postback === "STORE_PICKUP")) {

  deliveryMethod = "Pick-Up";
  deliveryAddress = null;
  isDeliverable = true;
  nextAction = "PAYMENT";

  if (rawInput[0] && rawInput[0].senderId) {
    psid = rawInput[0].senderId;
  } else if (rawInput.senderId) {
    psid = rawInput.senderId;
  }

} else {
  let formData;
  try {
    if (rawInput.body && typeof rawInput.body === 'object') {
      formData = rawInput.body;
    } else if (rawInput.body && typeof rawInput.body === 'string') {
      formData = JSON.parse(rawInput.body);
    } else {
      formData = rawInput;
    }
    psid = formData.psid || rawInput.psid || (rawInput.senderId || "unknown");
  } catch (e) {
    formData = rawInput;
    psid = formData.psid || "unknown";
  }

  const email = formData.email || '';
  const phone = formData.phone || '';
  const street = formData.street || '';
  const barangay = formData.barangay || '';
  const city = formData.city || '';
  const landmarks = formData.landmarks || '';
  const notes = formData.notes || '';
  const recipientName = formData.recipientName || '';
  const fullAddress = `${street}, ${barangay}, ${city}`;

  const supportedBarangays = [
    "Alapan I-A", "Alapan I-B", "Alapan I-C",
    "Bayan Luma 2", "Bayan Luma 3", "Bayan Luma 4", "Bayan Luma 5", "Bayan Luma 6", "Bayan Luma 7", "Bayan Luma 8", "Bayan Luma 9",
    "Buhay na Tubig", "Carsadang Bago 1", "Carsadang Bago 2", "Malagasang", "Toclong"
  ];

  isDeliverable = supportedBarangays.some(brgy =>
    barangay.toLowerCase().includes(brgy.toLowerCase())
  );

  deliveryAddress = {
    recipientName,
    email,
    phone,
    street,
    barangay,
    city,
    landmarks,
    notes,
    fullAddress,
    isDeliverable
  };

  nextAction = isDeliverable ? "PAYMENT" : "NOT_SERVICEABLE";
}

return {
  json: {
    userId: psid,
    deliveryMethod,
    deliveryAddress,
    updatedAt: formattedDate,
    nextAction,
    transactionId,
    paymentMethod
  }
};

const input = $input.first().json;

function formatDatePH(dateStr) {
  const date = new Date(dateStr);
  const offset = 8 * 60; // Philippines is UTC+8
  const localDate = new Date(date.getTime() + offset * 60000);
  const y = localDate.getFullYear();
  const m = String(localDate.getMonth() + 1).padStart(2, '0');
  const d = String(localDate.getDate()).padStart(2, '0');
  const h = String(localDate.getHours()).padStart(2, '0');
  const min = String(localDate.getMinutes()).padStart(2, '0');
  const s = String(localDate.getSeconds()).padStart(2, '0');
  return `${y}-${m}-${d} ${h}:${min}:${s}`;
}

const orderCart = input.items.map(item => ({
  ProductName: item.productName,
  ProductID: item.productId,
  Size: item.size,
  Addons: item.addOns ? item.addOns.map(addon => ({
    AddOnID: addon.ingredientId || addon.addOnId,
    Name: addon.ingredientName || addon.addOnName,
    BasePrice: addon.ingredientPrice || addon.addOnPrice,
    Quantity: addon.quantity // Include quantity if needed
  })) : [],
  Quantity: item.quantity,
  Price: item.totalPrice, // Assuming totalPrice includes base + addons
  ImageLink: item.imageLink || ""
}));

const isDelivery = input.deliveryMethod && input.deliveryMethod.toLowerCase().includes("delivery");

const subtotal = input.items.reduce((sum, item) => sum + item.totalPrice, 0);

const discountAmount = input.appliedPromo?.discountAmount || 0;

const customer = {
  userId: input.userId,
  fullname: $input.first().json.deliveryAddress.recipientName || "Unknown",
  email: input.deliveryAddress?.email || "",
  contactnumber: input.deliveryAddress?.phone || "",
  deliveryMethod: isDelivery ? "Delivery" : "Pick-Up",
  city: input.deliveryAddress?.city || "",
  address: `${input.deliveryAddress?.street || ""}, ${input.deliveryAddress?.barangay || ""}`.trim()
};

const order = {
  OrderID: input.transactionId || "",
  Date: formatDatePH(input.updatedAt || input.createdAt),
  Source: "Chatbot", // Or "Website" if applicable
  Cart: orderCart,
  Customer: customer,
  Total: subtotal + (isDelivery ? 20 : 0) - discountAmount, // Subtract discount here
  Notes: input.deliveryAddress?.notes || "",
  PaymentStatus: "Paid",
  FulfillmentStatus: "Preparing",
  FulfillmentMethod: isDelivery ? "Delivery" : "Pick-Up",
  PaymentMethod: "EWALLET", // Or dynamic based on Xendit data
  PaymentMode: input.paymentMethod || "E-Payment",
  XenditPaymentID: $('Order Confirmation For Delivery & Pickup [E-Pay]').first().json.body.payment_id || "", // Add if available from payment webhook
  PromoEventApplied: input.appliedPromo?.event || "",
  PromoDiscountAmount: discountAmount
};

return [{ json: order }];

