const orderData = $input.first().json;
const items = orderData.Cart || [];

const updates = [];

items.forEach(cartItem => {
  const quantity = parseInt(cartItem.Quantity) || 1;
  const productId = cartItem.ProductID;
  const size = cartItem.Size;

  // Pastries/Bites
  if (productId.startsWith('BK-')) {
    updates.push({
      type: 'pastrie',
      productId: productId,
      deduction: quantity
    });
  }

  // Milkteas
  if (productId.startsWith('MT-')) {
    updates.push({
      type: 'drink',
      productId: productId,
      size: size,
      deduction: quantity
    });
  }

  // Coffee
  if (productId.startsWith('CF-')) {
    updates.push({
      type: 'drink',
      productId: productId,
      size: size || "16oz",
      deduction: quantity
    });
  }

  // Fruit Tea
  if (productId.startsWith('FT-')) {
    updates.push({
      type: 'drink',
      productId: productId,
      size: size || "22oz",
      deduction: quantity
    });
  }

  // Add-ons
  if (cartItem.Addons && Array.isArray(cartItem.Addons)) {
    cartItem.Addons.forEach(addon => {
      const addonType = addon.AddOnID.startsWith('ING-') ? 'ingredient' : 'addon';
      updates.push({
        type: addonType,
        addonId: addon.AddOnID,
        deduction: (parseInt(addon.Quantity) || 1) * quantity
      });
    });
  }
});

return { json: { updates, itemsProcessed: items.length } };

