const items = $input.all().map(i => i.json);
const loopData = $('SplitInBatches1').all().map(i => i.json);

let ingredientDeductions = {};

items.forEach((product, index) => {
  const orderItem = loopData[index];
  if (!orderItem) {
    // Skip if no matching order data (optional: log or handle error)
    return;
  }

  const selectedSize = orderItem?.size;
  const deduction = orderItem?.deduction || 1;

  if (product.Ingredients && product.Ingredients.length > 0) {
    product.Ingredients.forEach(ingredient => {
      const ingredientId = ingredient.ingredientID;
      // Treat usedGrams as a number (not an object); if it's per size in full data, change to: ingredient.usedGrams[selectedSize] || 0
      const gramsNeeded = ingredient.usedGrams || 0;
      const totalGramsNeeded = gramsNeeded * deduction;

      if (!ingredientDeductions[ingredientId]) {
        ingredientDeductions[ingredientId] = 0;
      }
      ingredientDeductions[ingredientId] += totalGramsNeeded;
    });
  }
});

return Object.keys(ingredientDeductions).map(ingredientId => ({
