const items = $input.all().map(item => item.json);

// Aggregate deductions by IngredientID
const aggregated = {};

items.forEach(item => {
  if (item.IngredientID) {
    if (!aggregated[item.IngredientID]) {
      aggregated[item.IngredientID] = {
        totalDeduction: 0,
        currentQuantity: item.currentQuantity
      };
    }
    aggregated[item.IngredientID].totalDeduction += item.deduction;
  }
});

// Calculate new quantities
const results = Object.keys(aggregated).map(ingredientID => {
  const agg = aggregated[ingredientID];
  return {
    IngredientID: ingredientID,
    Amount: Math.max(0, agg.currentQuantity - agg.totalDeduction)
  };
});

return results;

const input = $input.first().json;
const body = input.body;  // Access the body of the webhook

const orderId = body.orderId;
const userId = body.userId.userId;  // Access the userId string from the object
const fulfillmentStatus = body.fulfillmentStatus;
const deliveryMethod = body.deliveryMethod;
const total = body.total;
const items = body.items;

let statusMessage = '';
let statusPercentage = 0;

switch (fulfillmentStatus) {
  case 'Preparing':
    statusPercentage = 25;
    statusMessage = 'Your order is now being prepared! (25%) We\'ll notify you when it\'s ready for delivery.';
    break;
  case 'In Progress':
    statusPercentage = 50;
    statusMessage = 'Your order is currently being prepared by our team. (50%)';
    break;
  case 'Ready':
    statusPercentage = 75;
    statusMessage = 'Your order is ready and will be out for delivery soon! (75%)';
    break;
  case 'In Delivery':
    statusPercentage = 90;
    statusMessage = 'Your order is out for delivery! It should arrive shortly. (90%)';
    break;
  case 'Completed':
    statusPercentage = 100;
    statusMessage = 'Your order has been delivered! Thank you for choosing Blessings Cafe! (100%)';
    break;
  case 'Cancelled':
    statusPercentage = 0;
    statusMessage = 'Your order has been cancelled. If you have questions, please contact us. (0%)';
    break;
  default:
    statusPercentage = 0;
    statusMessage = `Your order status has been updated to: ${fulfillmentStatus} (0%)`;
}

const itemSummary = items && items.length > 0 
  ? items.map(item => `${item.Quantity}x ${item.ProductName}`).join('\n')
  : 'View your order details';

return {
  json: {
    userId: userId,
    orderId: orderId,
    fulfillmentStatus: fulfillmentStatus,
    statusMessage: statusMessage,
    statusPercentage: statusPercentage,
    itemSummary: itemSummary,
    total: total,
    deliveryMethod: deliveryMethod
  }
};

