    break;
  case 'In Progress':
    statusPercentage = 50;
    statusMessage = 'Your order is currently being prepared by our team. (50%)';
    break;
  case 'Ready':
    statusPercentage = 75;
    statusMessage = 'Your order is ready for pickup! Please come to our store at your convenience. Blessings Cafe, Imus, Cavite (75%)';
    break;
  case 'Completed':
    statusPercentage = 100;
    statusMessage = 'Your order has been completed! Thank you for choosing Blessings Cafe! (100%)';
    break;
  case 'Cancelled':
    statusPercentage = 0;
    statusMessage = 'Your order has been cancelled. If you have questions, please contact us. (0%)';
    break;
  default:
    statusPercentage = 0;
    statusMessage = `Your order status has been updated to: ${fulfillmentStatus} (0%)`;
}

const itemSummary = items && items.length > 0 
  ? items.map(item => `${item.Quantity}x ${item.ProductName}`).join('\n')
  : 'View your order details';

return {
  json: {
    userId: userId,
    orderId: orderId,
    fulfillmentStatus: fulfillmentStatus,
    statusMessage: statusMessage,
    statusPercentage: statusPercentage,
    itemSummary: itemSummary,
    total: total,
    deliveryMethod: deliveryMethod
  }
};
